});

// ============================================================================
// AC3 — no `videoUrl` reference remains anywhere in source
// ============================================================================

const VIDEO_URL_TOKEN = ["video", "Url"].join("");

function listSourceFiles(dir: string): string[] {
	const files: string[] = [];
	for (const name of readdirSync(dir)) {
